      "title": "MultiPoint",
      "type": "object",
      "description": "A geographic object comprised of multiple points.",
      "example": "../examples/geometryObject.json",
      "translation": {
        "ISO 19115-2": [
          "EX_Extent > geographicElement > EX_BoundingPolygon > polygon > MultiGeometry > geometryMembers > Point[ ]"
        ]
